def kruskal(graph):
    parent = dict()

    def find(node):
        if parent[node] == node:
            return node
        return find(parent[node])

    def union(node1, node2):
        root1 = find(node1)
        root2 = find(node2)
        parent[root1] = root2

    minimum_spanning_tree = set()
    edges = list(graph['edges'])
    edges.sort(key=lambda edge: edge[2])

    for edge in edges:
